import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.B0LNVsFV.js";const p=JSON.parse('{"title":"12. Admin resources with NgRx","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/12-admin-resources-ngrx.md","filePath":"chapters/12-admin-resources-ngrx.md"}'),i={name:"chapters/12-admin-resources-ngrx.md"};function d(o,e,n,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_12-admin-resources-with-ngrx" tabindex="-1">12. Admin resources with NgRx <a class="header-anchor" href="#_12-admin-resources-with-ngrx" aria-label="Permalink to &quot;12. Admin resources with NgRx&quot;">​</a></h1><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h2><ul><li><a href="https://ngrx.io/guide/store/install" target="_blank" rel="noreferrer">NGRX Install</a></li><li><a href="https://ngrx.io/guide/effects" target="_blank" rel="noreferrer">NGRX Effects</a></li><li><a href="https://ngrx.io/guide/store/walkthrough" target="_blank" rel="noreferrer">NGRX Walkthrough</a></li><li><a href="https://ngrx.io/guide/store-devtools" target="_blank" rel="noreferrer">NGRX DevTools</a></li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><p>You can use Claude Code (set up in chapter 11) to implement this chapter.</p><ol><li>Install NgRx:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm i @ngrx/store@21 @ngrx/effects@21</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>Implement for beneficiaries:</li></ol><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Actions</td><td>Load, load success, create, create success, delete, delete success, failure</td></tr><tr><td>Reducer</td><td>Keeps the beneficiary list, a loaded flag and the last error. Success actions update the list</td></tr><tr><td>Effects</td><td>Load, create and delete call the beneficiaries service and answer with a success or failure action</td></tr><tr><td>Store setup</td><td>Register the store, the beneficiaries state and the effects for the whole app</td></tr><tr><td>Admin page</td><td>A form (first name, last name, email, job) and a list with a delete button. Only reads the store and dispatches actions</td></tr><tr><td>Navigation</td><td>A link to the page, shown only to superadmins. The route is also protected with the role guard</td></tr><tr><td>Contract form</td><td>The beneficiary dropdown now reads the store instead of calling the service directly</td></tr></tbody></table><ol start="3"><li>Repeat the same for insured objects (exercise):</li></ol><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Fields</td><td>Name, value (greater than 0) and at least one contract type</td></tr><tr><td>Service</td><td>List, create and delete insured objects</td></tr><tr><td>Page</td><td>Same layout as beneficiaries, showing the contract types of each object</td></tr><tr><td>Try it</td><td>Add an insured object for life insurance, then calculate the premium of a life contract again: the premium changes</td></tr></tbody></table><ol start="4"><li>Contracts do not use NgRx; they keep their services and signals.</li></ol><p>Test as <code>admin</code>: add and delete beneficiaries and insured objects. As <code>broker</code> the link is hidden and the route redirects to the list.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>Reducer: load success stores the list, create success adds, delete success removes, failure keeps the error message</li><li>Effects: a successful service answer gives the success action, a failing service gives the failure action</li><li>Do not use marble tests; feed the effect an action with <code>of(...)</code> and read the result with <code>firstValueFrom</code></li><li>Repeat the reducer and effect tests for insured objects</li><li>The contract form still validates after switching to the store</li></ul><p>Done when admins can manage both resources through the store, brokers cannot, and the tests are green.</p><h2 id="what-to-explain" tabindex="-1">What to explain <a class="header-anchor" href="#what-to-explain" aria-label="Permalink to &quot;What to explain&quot;">​</a></h2><ul><li>NgRx Logical Flow</li><li>NgRx Testing</li></ul>',18)])])}const f=t(i,[["render",d]]);export{p as __pageData,f as default};
